import React, { useEffect, useState } from "react";
import Navbar from "../Components/Navbar";
import Footer from "../Components/Footer";
import API_BASE_URL from "../config";

const MySales = () => {
  const userId = sessionStorage.getItem("userId");
  const [sales, setSales] = useState([]);
  const [payoutTotal, setPayoutTotal] = useState(0);

  useEffect(() => {
    const fetchSales = async () => {
      const res = await fetch(`${API_BASE_URL}/api/seller-orders/${userId}`);
      const data = await res.json();
      setSales(data);
      const total = data.reduce((sum, sale) => sum + parseFloat(sale.price || 0), 0);
      setPayoutTotal(total);
    };
    fetchSales();
  }, [userId]);

  const handlePayout = () => {
    const fee = payoutTotal * 0.05;
    const payout = payoutTotal - fee;
    alert(`💸 You were paid $${payout.toFixed(2)} after fees ($${fee.toFixed(2)})`);
    setPayoutTotal(0);
  };

  return (
    <div className="min-h-screen flex flex-col">
      <Navbar />
      <div className="p-4 flex-grow">
        <h2 className="text-xl font-bold mb-4">My Sales</h2>
        {sales.map((sale, index) => (
          <div key={index} className="border p-2 mb-2">
            <h3>{sale.title}</h3>
            <p>${sale.price}</p>
            <p>Buyer: {sale.buyer_name}</p>
          </div>
        ))}
        <div className="mt-4">
          <p className="font-bold">Total Payout: ${payoutTotal.toFixed(2)}</p>
          <button className="bg-blue-600 text-white px-4 py-2 mt-2" onClick={handlePayout}>Payout Now</button>
        </div>
      </div>
      <Footer />
    </div>
  );
};

export default MySales;
